/* Base Reset & Variables */
:root {
  --primary: #3861FB;
  --primary-hover: #294ACC;
  --text-main: #0D1421;
  --text-secondary: #808A9D;
  --bg-main: #FFFFFF;
  --bg-secondary: #F8FAFC;
  --bg-hover: #F1F5F9;
  --green: #16c784;
  --red: #ea3943;
  --border: #EFF2F5;
  --border-dark: #E2E8F0;

  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --shadow-dropdown: 0 4px 20px rgba(0, 0, 0, 0.08);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text-main);
  background-color: var(--bg-main);
  line-height: 1.5;
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--primary);
  text-decoration: none;
  cursor: pointer;
}
a:hover { text-decoration: underline; }

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

ul { list-style: none; }

/* Utilities */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 24px;
}
.flex { display: flex; }
.flex-col { display: flex; flex-direction: column; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.justify-center { justify-content: center; }
.gap-1 { gap: 4px; }
.gap-2 { gap: 8px; }
.gap-3 { gap: 12px; }
.gap-4 { gap: 16px; }
.gap-6 { gap: 24px; }
.gap-8 { gap: 32px; }

.text-sm { font-size: 12px; }
.text-base { font-size: 14px; }
.text-lg { font-size: 16px; }
.text-xl { font-size: 20px; }
.text-2xl { font-size: 24px; }

.font-medium { font-weight: 500; }
.font-semibold { font-weight: 600; }
.font-bold { font-weight: 700; }

.text-secondary { color: var(--text-secondary); }
.text-green { color: var(--green); }
.text-red { color: var(--red); }
.tabular-nums { font-variant-numeric: tabular-nums; }
.right-align { text-align: right; }

.btn {
  padding: 8px 16px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 14px;
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.btn-primary {
  background-color: var(--primary);
  color: #fff;
}
.btn-primary:hover { background-color: var(--primary-hover); text-decoration: none; }
.btn-outline {
  border: 1px solid var(--border-dark);
  background: transparent;
  color: var(--text-main);
}
.btn-outline:hover { background: var(--bg-hover); text-decoration: none;}

/* Top Bar Stats */
.top-stats-bar {
  background-color: var(--bg-main);
  border-bottom: 1px solid var(--border);
  padding: 8px 0;
  font-size: 12px;
  color: var(--text-secondary);
}
.top-stats-bar .stat-item {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-right: 24px;
}
.top-stats-bar .stat-value {
  color: var(--text-main);
  font-weight: 600;
}

/* Header */
.main-header {
  border-bottom: 1px solid var(--border);
  background: var(--bg-main);
  position: sticky;
  top: 0;
  z-index: 100;
}
.main-header-inner {
  height: 64px;
}
.logo {
  font-size: 20px;
  font-weight: 700;
  color: var(--text-main);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
}
.logo-icon {
  width: 28px;
  height: 28px;
  background-color: var(--primary);
  border-radius: 6px;
  display: inline-block;
  position: relative;
}
.logo-icon::after {
  content: '';
  position: absolute;
  top: 6px; left: 6px; right: 6px; bottom: 6px;
  border: 2px solid #fff;
  border-radius: 50%;
}
.main-nav { margin-left: 32px; }
.main-nav a {
  color: var(--text-main);
  font-weight: 600;
  font-size: 14px;
  padding: 8px 12px;
  border-radius: 6px;
  text-decoration: none;
}
.main-nav a:hover { background: var(--bg-hover); }
.header-actions { margin-left: auto; }

/* Promotional Banner */
.promo-banner {
  background: linear-gradient(90deg, rgba(56,97,251,0.1) 0%, rgba(56,97,251,0.05) 100%);
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
  text-align: center;
  font-weight: 500;
  cursor: pointer;
}
.promo-banner:hover { background: linear-gradient(90deg, rgba(56,97,251,0.15) 0%, rgba(56,97,251,0.1) 100%); }

/* AI Alerts */
.ai-alerts {
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
  background: var(--bg-secondary);
  font-size: 13px;
}
.ai-badge {
  background: linear-gradient(135deg, #A855F7, #3B82F6);
  color: white;
  padding: 2px 8px;
  border-radius: 12px;
  font-weight: 700;
  font-size: 11px;
}
.ai-pills {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.ai-pills::-webkit-scrollbar { display: none; }
.ai-pill {
  white-space: nowrap;
  background: var(--bg-main);
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 4px 12px;
  cursor: pointer;
  color: var(--text-secondary);
  transition: all 0.2s;
}
.ai-pill:hover { border-color: var(--primary); color: var(--primary); }

/* Main Content area */
.page-header { margin: 32px 0 24px; }
.page-header h1 { font-size: 24px; font-weight: 700; margin-bottom: 8px; }
.market-summary { color: var(--text-secondary); line-height: 1.6; max-width: 900px; }
.market-summary strong { color: var(--text-main); }
.read-more-btn { color: var(--primary); background: none; border: none; font-weight: 600; cursor: pointer; padding: 0; }
.read-more-btn:hover { text-decoration: underline; }
.summary-extra { display: none; margin-top: 8px; }
.summary-extra.active { display: inline; }

/* Tabs System */
.tabs-row {
  display: flex;
  gap: 8px;
  border-bottom: 1px solid var(--border);
  margin-bottom: 16px;
  overflow-x: auto;
}
.tab {
  padding: 12px 16px;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  cursor: pointer;
  white-space: nowrap;
}
.tab:hover { color: var(--text-main); }
.tab.active {
  color: var(--primary);
  border-bottom-color: var(--primary);
}

.controls-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
  flex-wrap: wrap;
  gap: 16px;
}
.network-pills { display: flex; gap: 8px; overflow-x: auto; }
.network-pill {
  padding: 6px 12px;
  border-radius: 8px;
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 13px;
  cursor: pointer;
  border: 1px solid transparent;
  white-space: nowrap;
}
.network-pill:hover { background: var(--border); }
.network-pill.active {
  background: var(--primary);
  color: white;
}

/* Table Controls Panels */
.panel {
  display: none;
  background: var(--bg-main);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
  box-shadow: var(--shadow-sm);
}
.panel.active { display: block; }
.panel h3 { font-size: 14px; margin-bottom: 12px; }

/* Data Table */
.table-container {
  overflow-x: auto;
  margin-bottom: 24px;
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  background: var(--bg-main);
}
.crypto-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  text-align: right;
}
.crypto-table th, .crypto-table td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}
.crypto-table th {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-main);
  position: sticky;
  top: 0;
  z-index: 10;
  user-select: none;
  cursor: pointer;
}
.crypto-table th:hover { color: var(--text-main); }
.crypto-table th.sortable::after {
  content: '▾';
  margin-left: 4px;
  opacity: 0.5;
}
.crypto-table tr:hover td { background-color: var(--bg-hover); }
.crypto-table tr:last-child td { border-bottom: none; }

/* Sticky Left Columns */
.crypto-table th:nth-child(1), .crypto-table td:nth-child(1) { text-align: left; position: sticky; left: 0; background: var(--bg-main); z-index: 11; width: 40px; }
.crypto-table th:nth-child(2), .crypto-table td:nth-child(2) { text-align: left; position: sticky; left: 40px; background: var(--bg-main); z-index: 11; }
.crypto-table tr:hover td:nth-child(1), .crypto-table tr:hover td:nth-child(2) { background-color: var(--bg-hover); }
.crypto-table td.rank { color: var(--text-secondary); font-size: 13px; font-weight: 500;}

/* Coin Name Cell */
.coin-name-cell { display: flex; align-items: center; gap: 12px; }
.coin-icon { width: 24px; height: 24px; border-radius: 50%; object-fit: cover; background: var(--bg-secondary); }
.coin-info { display: flex; align-items: center; gap: 8px; }
.coin-name { font-weight: 600; color: var(--text-main); }
.coin-symbol { color: var(--text-secondary); font-size: 12px; font-weight: 500; }

/* Sparkline */
.sparkline { height: 32px; width: 100px; display: inline-flex; align-items: flex-end; gap: 2px; }
.sparkline-bar { width: 4px; background-color: var(--text-secondary); border-radius: 1px 1px 0 0; }
.sparkline-bar.green { background-color: var(--green); }
.sparkline-bar.red { background-color: var(--red); }

/* Pagination */
.pagination {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  margin-bottom: 48px;
}
.page-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-weight: 500;
  color: var(--text-main);
  background: var(--bg-main);
  border: 1px solid var(--border);
  transition: all 0.2s;
}
.page-btn:hover { border-color: var(--primary); color: var(--primary); }
.page-btn.active { background: var(--primary); color: white; border-color: var(--primary); }
.page-ellipsis { color: var(--text-secondary); }

/* Info Section */
.info-section {
  padding: 48px 0;
  border-top: 1px solid var(--border);
  margin-top: 48px;
}
.info-content h2 { font-size: 20px; font-weight: 700; margin-bottom: 16px; margin-top: 32px; }
.info-content h2:first-child { margin-top: 0; }
.info-content p { color: var(--text-secondary); margin-bottom: 16px; max-width: 800px; }

/* Footer */
.main-footer {
  border-top: 1px solid var(--border);
  padding: 48px 0 24px;
  background: var(--bg-secondary);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 32px;
  margin-bottom: 48px;
}
.footer-col h4 { font-weight: 600; margin-bottom: 16px; color: var(--text-main); }
.footer-col ul { display: flex; flex-direction: column; gap: 12px; }
.footer-col a { color: var(--text-secondary); font-size: 14px; }
.footer-col a:hover { color: var(--primary); }
.footer-bottom {
  border-top: 1px solid var(--border-dark);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  color: var(--text-secondary);
  font-size: 14px;
}

/* Responsive */
@media (max-width: 1024px) {
  .main-nav { display: none; }
}
@media (max-width: 768px) {
  .controls-row { flex-direction: column; align-items: flex-start; }
  .top-stats-bar { overflow-x: auto; white-space: nowrap; }
}

document.addEventListener('DOMContentLoaded', () => {
  // 1. Data Generation
  const initialData = [
    { rank: 1, name: 'Bitcoin', symbol: 'BTC', price: '$75,612.78', h1: '+0.45%', h24: '+1.33%', d7: '+4.84%', marketCap: '$1.51T', volume: '$42.82B', supply: '20.01M BTC', color: '#F7931A' },
    { rank: 2, name: 'Ethereum', symbol: 'ETH', price: '$2,356.00', h1: '+0.51%', h24: '+0.80%', d7: '+6.29%', marketCap: '$284.35B', volume: '$21.36B', supply: '120.69M ETH', color: '#627EEA' },
    { rank: 3, name: 'Tether', symbol: 'USDT', price: '$1.00', h1: '+0.01%', h24: '+0.03%', d7: '+0.01%', marketCap: '$185.84B', volume: '$138.79B', supply: '185.8B USDT', color: '#26A17B' },
    { rank: 4, name: 'XRP', symbol: 'XRP', price: '$1.44', h1: '+0.71%', h24: '+2.71%', d7: '+7.89%', marketCap: '$89.13B', volume: '$4.03B', supply: '61.56B XRP', color: '#23292F' },
    { rank: 5, name: 'BNB', symbol: 'BNB', price: '$632.59', h1: '+0.38%', h24: '+1.89%', d7: '+4.98%', marketCap: '$85.27B', volume: '$1.95B', supply: '134.78M BNB', color: '#F3BA2F' },
    { rank: 6, name: 'USDC', symbol: 'USDC', price: '$1.00', h1: '-0.01%', h24: '-0.02%', d7: '+0.01%', marketCap: '$34.12B', volume: '$4.50B', supply: '34.12B USDC', color: '#2775CA' },
    { rank: 7, name: 'Solana', symbol: 'SOL', price: '$88.25', h1: '+0.67%', h24: '+3.74%', d7: '+5.67%', marketCap: '$50.77B', volume: '$6.71B', supply: '575.26M SOL', color: '#14F195' },
  ];

  const generateMockData = () => {
    const data = [...initialData];
    const names = ['Cardano', 'Dogecoin', 'TRON', 'Toncoin', 'Chainlink', 'Polkadot', 'Polygon', 'Shiba Inu', 'Litecoin', 'Bitcoin Cash', 'Avalanche', 'Uniswap', 'Cosmos', 'Stellar', 'Monero', 'Ethereum Classic', 'Aptos', 'Filecoin', 'Arbitrum', 'VeChain', 'Maker', 'Render', 'Optimism', 'Injective', 'Sui'];
    const symbols = ['ADA', 'DOGE', 'TRX', 'TON', 'LINK', 'DOT', 'MATIC', 'SHIB', 'LTC', 'BCH', 'AVAX', 'UNI', 'ATOM', 'XLM', 'XMR', 'ETC', 'APT', 'FIL', 'ARB', 'VET', 'MKR', 'RNDR', 'OP', 'INJ', 'SUI'];

    for (let i = 8; i <= 100; i++) {
      const isPositive = Math.random() > 0.4;
      const randIdx = Math.floor(Math.random() * names.length);
      const h1Val = (Math.random() * 2).toFixed(2);
      const h24Val = (Math.random() * 8).toFixed(2);
      const d7Val = (Math.random() * 15).toFixed(2);
      const price = (Math.random() * 100).toFixed(2);
      const cap = (Math.random() * 10 + 1).toFixed(2);
      const vol = (Math.random() * 2).toFixed(2);

      data.push({
        rank: i,
        name: names[randIdx],
        symbol: symbols[randIdx],
        price: `$${price}`,
        h1: isPositive ? `+${h1Val}%` : `-${h1Val}%`,
        h24: (Math.random() > 0.5 ? '+' : '-') + `${h24Val}%`,
        d7: (Math.random() > 0.5 ? '+' : '-') + `${d7Val}%`,
        marketCap: `$${cap}B`,
        volume: `$${vol}B`,
        supply: `${(Math.random() * 900 + 10).toFixed(0)}M ${symbols[randIdx]}`,
        color: `hsl(${Math.random() * 360}, 70%, 50%)`
      });
    }
    return data;
  };

  let cryptoData = generateMockData();

  const getPercentColor = (str) => {
    if (str.includes('+')) return 'text-green';
    if (str.includes('-')) return 'text-red';
    return '';
  };

  const generateSparkline = (isPositive) => {
    let bars = '';
    const colorClass = isPositive ? 'green' : 'red';
    let prevHeight = isPositive ? 20 : 80;

    for (let i = 0; i < 15; i++) {
      let height = prevHeight + (Math.random() * 30 - 15);
      height = Math.max(10, Math.min(100, height)); // clamp 10-100
      prevHeight = height;
      bars += `<div class="sparkline-bar ${colorClass}" style="height: ${height}%"></div>`;
    }
    return `<div class="sparkline">${bars}</div>`;
  };

  const renderTable = (data) => {
    const tbody = document.getElementById('tableBody');
    tbody.innerHTML = '';

    data.forEach(coin => {
      const isPositive7d = !coin.d7.includes('-');
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td class="rank">${coin.rank}</td>
        <td class="coin-name-cell">
          <div class="coin-icon flex items-center justify-center text-xs font-bold text-white" style="background:${coin.color}">${coin.symbol.charAt(0)}</div>
          <div class="coin-info">
            <span class="coin-name">${coin.name}</span>
            <span class="coin-symbol">${coin.symbol}</span>
          </div>
        </td>
        <td class="tabular-nums font-medium">${coin.price}</td>
        <td class="tabular-nums font-medium ${getPercentColor(coin.h1)}">${coin.h1}</td>
        <td class="tabular-nums font-medium ${getPercentColor(coin.h24)}">${coin.h24}</td>
        <td class="tabular-nums font-medium ${getPercentColor(coin.d7)}">${coin.d7}</td>
        <td class="tabular-nums font-medium">${coin.marketCap}</td>
        <td class="tabular-nums font-medium">${coin.volume}</td>
        <td class="tabular-nums">${coin.supply}</td>
        <td>${generateSparkline(isPositive7d)}</td>
      `;
      tbody.appendChild(tr);
    });
  };

  renderTable(cryptoData);

  // 2. Tab filtering
  const handleTabs = (selector, randomize = true) => {
    const tabs = document.querySelectorAll(selector);
    tabs.forEach(tab => {
      tab.addEventListener('click', () => {
        tabs.forEach(t => t.classList.remove('active'));
        tab.classList.add('active');
        if (randomize) {
          // Simulate fetching new data by scrambling the current array (except top 3 for effect)
          const top = cryptoData.slice(0, 3);
          const rest = cryptoData.slice(3).sort(() => Math.random() - 0.5);
          renderTable([...top, ...rest]);
        }
      });
    });
  };

  handleTabs('#categoryTabs .tab');
  handleTabs('#networkFilters .network-pill');

  // 3. Toggles
  const toggleBtn = (btnId, panelId) => {
    const btn = document.getElementById(btnId);
    const panel = document.getElementById(panelId);
    btn.addEventListener('click', () => {
      const isActive = panel.classList.contains('active');
      document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
      if (!isActive) panel.classList.add('active');
    });
  };
  toggleBtn('toggleColumnsBtn', 'columnsPanel');
  toggleBtn('toggleFiltersBtn', 'filtersPanel');

  // 4. Read More
  const readMoreBtn = document.getElementById('readMoreBtn');
  const summaryExtra = document.getElementById('summaryExtra');
  readMoreBtn.addEventListener('click', () => {
    const isActive = summaryExtra.classList.contains('active');
    if (isActive) {
      summaryExtra.classList.remove('active');
      readMoreBtn.textContent = '[Read More]';
    } else {
      summaryExtra.classList.add('active');
      readMoreBtn.textContent = '[Read Less]';
    }
  });

  // 5. Promotional Banner Carousel
  const bannerMessages = [
    "CTP Launch: Secure $GENIUS Airdrop — Join Now",
    "Partner Feature: 0% Trading Fees on New Pairs",
    "Ecosystem Update: V2 API Now Available"
  ];
  let currentBannerIdx = 0;
  const promoText = document.getElementById('promoText');
  setInterval(() => {
    currentBannerIdx = (currentBannerIdx + 1) % bannerMessages.length;
    promoText.style.opacity = '0';
    setTimeout(() => {
      promoText.textContent = bannerMessages[currentBannerIdx];
      promoText.style.opacity = '1';
    }, 300);
  }, 4000);
  // Add simple fade transition to promo text
  promoText.style.transition = 'opacity 0.3s ease';

  // 6. Pagination
  const renderPagination = () => {
    const pages = [1, 2, 3, 4, '...', 84];
    const pagContainer = document.getElementById('pagination');
    let html = '';
    pages.forEach((p, idx) => {
      if (p === '...') {
        html += `<span class="page-ellipsis">...</span>`;
      } else {
        const activeClass = idx === 0 ? 'active' : '';
        html += `<button class="page-btn ${activeClass}">${p}</button>`;
      }
    });
    pagContainer.innerHTML = html;

    const pageBtns = pagContainer.querySelectorAll('.page-btn');
    pageBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        pageBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        // Simulate data load
        renderTable(cryptoData.sort(() => Math.random() - 0.5));
        window.scrollTo({ top: document.querySelector('.table-container').offsetTop - 100, behavior: 'smooth' });
      });
    });
  };

  renderPagination();
});
